using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

// Local Blender geometry. No API calls, credits or raster billboards.
public sealed class Refined3DImporter:AssetPostprocessor {
 void OnPreprocessModel(){if(!assetPath.Contains("/Models/Refined3D/")||!assetPath.EndsWith(".fbx"))return;var importer=(ModelImporter)assetImporter;importer.globalScale=1;importer.useFileScale=true;importer.bakeAxisConversion=true;importer.isReadable=true;importer.importAnimation=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.importCameras=false;importer.importLights=false;importer.meshCompression=ModelImporterMeshCompression.Off;importer.optimizeMeshPolygons=true;importer.optimizeMeshVertices=true;importer.importNormals=ModelImporterNormals.Import;}
}
public static class Refined3DBuilder {
 const string Models="Assets/Models/Refined3D",Root="Assets/Resources/Final3D",Version="local-blender-v15-r4";
 [Serializable] sealed class Swatch {public string name;public float[] color;public float metallic,roughness,emission;}
 [Serializable] sealed class Palette {public Swatch[] materials;}
 static Dictionary<string,Swatch> palette;
 static readonly Dictionary<string,Material> materialCache=new Dictionary<string,Material>();
 public static void EnsureAssets(){string stamp=Root+"/refined-v15.json";var hero=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/hero-0-0.prefab");if(!File.Exists(stamp)||!File.ReadAllText(stamp).Contains(Version)||hero==null||hero.transform.Find("RefinedBlenderV15")==null)BuildAll();}
 [MenuItem(NoiteSemFim.GameIdentity.Title + "/3D/Aplicar modelos Blender refinados")]
 public static void BuildAll(){AssetDatabase.Refresh();palette=JsonUtility.FromJson<Palette>(File.ReadAllText(Models+"/palette-v15.json")).materials.ToDictionary(p=>p.name);materialCache.Clear();Directory.CreateDirectory(Root+"/RefinedMeshes");Directory.CreateDirectory(Root+"/RefinedMaterials");
  for(int hero=0;hero<3;hero++)for(int armor=0;armor<5;armor++)Build(new[]{"lia","caio","iris"}[hero]+"-refined-v15", "hero-"+hero+"-"+armor,armor,false);
  for(int dragon=0;dragon<3;dragon++)Build("brasa-refined-v15","dragon-"+dragon,dragon,true);
  foreach(var family in new[]{new KeyValuePair<string,int>("enemy",8),new KeyValuePair<string,int>("prop",12),new KeyValuePair<string,int>("relic",8),new KeyValuePair<string,int>("loot",4),new KeyValuePair<string,int>("ability",8),new KeyValuePair<string,int>("ground",4),new KeyValuePair<string,int>("status",6)})for(int i=0;i<family.Value;i++)Build(family.Key+"-"+i+"-refined-v15",family.Key+"-"+i,0,false);Build("arena-refined-v15","arena",0,false);
  File.WriteAllText(Root+"/refined-v15.json","{\"revision\":\""+Version+"\",\"heroVariants\":15,\"dragonVariants\":3,\"source\":\"local Blender; FBX; articulated pivots\"}");AssetDatabase.SaveAssets();AssetDatabase.Refresh();Verify();Debug.Log("REFINED BLENDER 3D: 69 final-phase prefabs rebuilt from 55 local Blender models.");
 }
 static void Build(string source,string target,int variant,bool dragon){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(Models+"/"+source+".fbx");if(asset==null)throw new Exception("Missing Blender FBX "+source);var imported=(GameObject)PrefabUtility.InstantiatePrefab(asset);PrefabUtility.UnpackPrefabInstance(imported,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var go=new GameObject(target);imported.name=source;imported.transform.SetParent(go.transform,false);imported.transform.localRotation=Quaternion.Euler(0,180,0)*imported.transform.localRotation;var marker=new GameObject("RefinedBlenderV15");marker.transform.SetParent(go.transform,false);
  foreach(var t in go.GetComponentsInChildren<Transform>(true)){string simple=t.name.Split('.')[0];if(new[]{"ArmL","ArmR","LegL","LegR","Head","Tail","WingL","WingR","Cape","Jaw"}.Contains(simple))t.name=simple;}
  foreach(var renderer in go.GetComponentsInChildren<MeshRenderer>()){var mapped=renderer.sharedMaterials;for(int i=0;i<mapped.Length;i++){string key=mapped[i]!=null?mapped[i].name.Split('.')[0]:"NSF_Navy";mapped[i]=MaterialFor(key,variant,dragon);}renderer.sharedMaterials=mapped;renderer.shadowCastingMode=ShadowCastingMode.On;renderer.receiveShadows=true;}
  Optimize(go,source,variant,dragon);if(target.StartsWith("ability-")||target.StartsWith("ground-")||target.StartsWith("status-"))foreach(var renderer in go.GetComponentsInChildren<MeshRenderer>()){renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;}
  // Distinct worn breastplates, in addition to per-set cloak and jewel palettes.
  if(target.StartsWith("hero-")&&variant>0){var torso=go.GetComponentsInChildren<MeshFilter>().FirstOrDefault(m=>m.name.Contains("FittedBodice"));if(torso==null)torso=go.GetComponentsInChildren<MeshFilter>().FirstOrDefault(m=>m.sharedMesh!=null&&m.name.Contains("Navy"));if(torso!=null){var plate=new GameObject("EquippedBreastplate");plate.transform.SetParent(torso.transform.parent,false);plate.transform.localPosition=torso.transform.localPosition;plate.transform.localRotation=torso.transform.localRotation;plate.transform.localScale=torso.transform.localScale*1.035f;plate.AddComponent<MeshFilter>().sharedMesh=torso.sharedMesh;plate.AddComponent<MeshRenderer>().sharedMaterial=MaterialFor(variant==2?"NSF_White":variant==3?"NSF_Leather":"NSF_Gold",variant,false);}}
  PrefabUtility.SaveAsPrefabAsset(go,Root+"/"+target+".prefab");UnityEngine.Object.DestroyImmediate(go);
 }
 static Material MaterialFor(string key,int variant,bool dragon){string cache=key+"-"+(dragon?"dragon-":"lia-")+variant;if(materialCache.TryGetValue(cache,out var cached))return cached;if(!palette.TryGetValue(key,out var swatch))swatch=palette["NSF_Navy"];var color=new Color(swatch.color[0],swatch.color[1],swatch.color[2]);float metal=swatch.metallic;
  if(!dragon&&variant>0&&(key=="NSF_Navy"||key=="NSF_Blue"||key=="NSF_Velvet"||key=="NSF_Teal"||key=="NSF_Ivory")){Color tint=variant==1?new Color(.035f,.18f,.12f):variant==2?new Color(.035f,.17f,.31f):variant==3?new Color(.19f,.025f,.02f):new Color(.13f,.035f,.22f);color=Color.Lerp(tint,tint*1.7f,key=="NSF_Blue"?1:0);}
  if(dragon&&variant>0){if(key=="NSF_Red"||key=="NSF_RedLight"||key=="NSF_Wing"||key=="NSF_WingEdge"){float light=key=="NSF_RedLight"?1.6f:key=="NSF_Wing"?2:key=="NSF_WingEdge"?.5f:1;color=(variant==1?new Color(.018f,.15f,.48f):new Color(.22f,.035f,.39f))*light;}if(key=="NSF_Ember")color=variant==1?new Color(.04f,.65f,1):new Color(1,.65f,.14f);if(key=="NSF_Belly")color=variant==1?new Color(.28f,.70f,.83f):new Color(.95f,.62f,.24f);}
  if(!dragon&&variant>0&&key=="NSF_Arcane")color=variant==1?new Color(.04f,.6f,.24f):variant==2?new Color(.04f,.65f,1):variant==3?new Color(1,.17f,.02f):new Color(.55f,.1f,1);
  var material=new Material(Shader.Find("Standard")){name=cache,color=color.gamma,enableInstancing=true};if(key=="NSF_Stone"){material.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Textures/floor-albedo-v14.png");material.color=new Color(.65f,.72f,.82f);}material.SetFloat("_Metallic",metal);material.SetFloat("_Glossiness",1-swatch.roughness);if(swatch.emission>0){material.EnableKeyword("_EMISSION");material.SetColor("_EmissionColor",color*swatch.emission);}
  string path=Root+"/RefinedMaterials/"+cache+".mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing!=null){EditorUtility.CopySerialized(material,existing);UnityEngine.Object.DestroyImmediate(material);material=existing;}else AssetDatabase.CreateAsset(material,path);materialCache[cache]=material;return material;
 }
 static void Optimize(GameObject go,string source,int variant,bool dragon){int group=0;foreach(var parent in go.GetComponentsInChildren<Transform>(true).ToArray()){if(parent==null)continue;var leaves=new List<MeshFilter>();foreach(Transform child in parent){var filter=child.GetComponent<MeshFilter>();if(filter!=null&&filter.sharedMesh!=null&&child.childCount==0&&child.GetComponent<MeshRenderer>()!=null)leaves.Add(filter);}foreach(var materialGroup in leaves.GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial)){var list=materialGroup.ToArray();if(list.Length<2)continue;var combine=list.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=parent.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{name=source+"-group-"+group,indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(combine,true,true);mesh.RecalculateBounds();string path=Root+"/RefinedMeshes/"+source+"-"+variant+"-"+(group++)+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,path);var merged=new GameObject("Merged_"+materialGroup.Key.name);merged.transform.SetParent(parent,false);merged.AddComponent<MeshFilter>().sharedMesh=mesh;merged.AddComponent<MeshRenderer>().sharedMaterial=materialGroup.Key;foreach(var original in list)UnityEngine.Object.DestroyImmediate(original.gameObject);}}
 }
 [MenuItem(NoiteSemFim.GameIdentity.Title + "/3D/Verificar modelos refinados")]
 public static void Verify(){var lines=new List<string>();var expected=new List<string>();for(int h=0;h<3;h++)for(int a=0;a<5;a++)expected.Add("hero-"+h+"-"+a);foreach(var pair in new[]{new KeyValuePair<string,int>("dragon",3),new KeyValuePair<string,int>("enemy",8),new KeyValuePair<string,int>("prop",12),new KeyValuePair<string,int>("relic",8),new KeyValuePair<string,int>("loot",4),new KeyValuePair<string,int>("ability",8),new KeyValuePair<string,int>("ground",4),new KeyValuePair<string,int>("status",6)})for(int i=0;i<pair.Value;i++)expected.Add(pair.Key+"-"+i);expected.Add("arena");foreach(var name in expected){var go=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/"+name+".prefab");if(go==null)throw new Exception("Missing refined prefab "+name);var filters=go.GetComponentsInChildren<MeshFilter>();int vertices=filters.Sum(f=>f.sharedMesh.vertexCount);if(vertices<3||((name.StartsWith("hero")||name.StartsWith("dragon"))&&vertices<3000))throw new Exception("Refined geometry not installed: "+name);var names=go.GetComponentsInChildren<Transform>().Select(t=>t.name).ToArray();foreach(var joint in name.StartsWith("hero")?new[]{"Head","ArmL","ArmR","LegL","LegR","Cape"}:name.StartsWith("dragon")?new[]{"Head","WingL","WingR","Tail","Jaw"}:name.StartsWith("enemy")?new[]{"Head"}:Array.Empty<string>())if(!names.Contains(joint))throw new Exception("Missing articulated joint "+name+" "+joint);var instance=UnityEngine.Object.Instantiate(go);var bounds=new Bounds(Vector3.zero,Vector3.zero);foreach(var r in instance.GetComponentsInChildren<MeshRenderer>())bounds.Encapsulate(r.bounds);if((name.StartsWith("hero")||name.StartsWith("dragon"))&&(bounds.size.y<1||bounds.size.y>4||bounds.size.x>5))throw new Exception("Incorrect refined model scale "+name+" "+bounds);UnityEngine.Object.DestroyImmediate(instance);lines.Add(name+": "+filters.Length+" mesh groups, "+vertices+" vertices; named joints, material and scale PASS");}File.WriteAllText("VERIFICACAO-MODELOS-V15.txt",string.Join("\n",lines));Debug.Log(string.Join("\n",lines));}
}
